#!/usr/bin/env node
// Regenerates every platform file that is derived from /shared, so the Mac and
// Windows apps cannot drift apart in look or sample data.
//
//   node scripts/sync-shared.mjs          write the generated files
//   node scripts/sync-shared.mjs --check  exit 1 if any generated file is stale (CI)
//
// Inputs:  shared/design/tokens.json, shared/data/seed.json, shared/fonts/*, shared/logo.png
// Outputs: apple/Sources/KeystoneApp/Theme/Tokens.swift
//          apple/Sources/KeystoneCore/Generated/SeedData.swift
//          apple/Sources/KeystoneApp/Resources/{fonts,logo.png}
//          windows/Keystone/Theme/Tokens.xaml
//          windows/Keystone/Assets/{fonts,logo.png,seed.json}

import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const check = process.argv.includes('--check');
const stale = [];

const HEADER = 'Generated by scripts/sync-shared.mjs from /shared. Do not edit by hand.';

function emit(rel, content) {
  const path = join(root, rel);
  const next = Buffer.isBuffer(content) ? content : Buffer.from(content);
  const prev = existsSync(path) ? readFileSync(path) : null;
  if (prev && prev.equals(next)) return;
  if (check) { stale.push(rel); return; }
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, next);
  console.log('wrote', rel);
}

const tokens = JSON.parse(readFileSync(join(root, 'shared/design/tokens.json'), 'utf8'));
const seedText = readFileSync(join(root, 'shared/data/seed.json'), 'utf8');
JSON.parse(seedText); // fail loudly on a broken seed before generating anything

// "#rrggbb" or "#rrggbbaa" -> [r, g, b, a] as 0-255
function rgba(hex) {
  const h = hex.replace('#', '');
  const n = (i) => parseInt(h.slice(i, i + 2), 16);
  return [n(0), n(2), n(4), h.length === 8 ? n(6) : 255];
}
const num = (v) => (Number.isInteger(v) ? `${v}` : `${v}`);

/* ---------- Swift ---------- */
{
  const colors = Object.entries(tokens.color).map(([k, v]) => {
    const [r, g, b, a] = rgba(v);
    const alpha = a === 255 ? '' : `, opacity: ${(a / 255).toFixed(3)}`;
    return `        static let ${k} = Color(red: ${(r / 255).toFixed(4)}, green: ${(g / 255).toFixed(4)}, blue: ${(b / 255).toFixed(4)}${alpha}) // ${v}`;
  });
  const group = (name, obj) =>
    `    enum ${name} {\n${Object.entries(obj).map(([k, v]) => `        static let ${k}: CGFloat = ${num(v)}`).join('\n')}\n    }`;
  const swift = `// ${HEADER}

import SwiftUI

enum Tokens {
    enum Palette {
${colors.join('\n')}
    }

    enum FontName {
        static let display = "${tokens.font.display}"
        static let body = "${tokens.font.body}"
${Object.entries(tokens.font.bodyFiles).map(([k, v]) => `        static let ${k} = "${v}"`).join('\n')}
    }

${group('Size', tokens.size)}

${group('Radius', tokens.radius)}

${group('Space', tokens.space)}

${group('Layout', tokens.layout)}
}
`;
  emit('apple/Sources/KeystoneApp/Theme/Tokens.swift', swift);

  if (seedText.includes('"##')) throw new Error('seed.json contains "## which would end the Swift raw string');
  emit('apple/Sources/KeystoneCore/Generated/SeedData.swift', `// ${HEADER}

enum SeedData {
    static let json = ##"""
${seedText.replace(/\n$/, '')}
"""##
}
`);
}

/* ---------- WinUI (XAML ResourceDictionary) ---------- */
{
  const hexArgb = (v) => {
    const [r, g, b, a] = rgba(v);
    return '#' + [a, r, g, b].map((x) => x.toString(16).padStart(2, '0')).join('').toUpperCase();
  };
  const cap = (s) => s[0].toUpperCase() + s.slice(1);
  const lines = [];
  for (const [k, v] of Object.entries(tokens.color)) {
    lines.push(`    <Color x:Key="${cap(k)}Color">${hexArgb(v)}</Color>`);
    lines.push(`    <SolidColorBrush x:Key="${cap(k)}Brush" Color="{StaticResource ${cap(k)}Color}" />`);
  }
  lines.push('');
  lines.push(`    <FontFamily x:Key="DisplayFont">ms-appx:///Assets/Fonts/Orbitron.ttf#${tokens.font.display}</FontFamily>`);
  lines.push(`    <FontFamily x:Key="BodyFont">ms-appx:///Assets/Fonts/Poppins-Regular.ttf#${tokens.font.body}</FontFamily>`);
  for (const group of ['size', 'radius', 'space', 'layout']) {
    lines.push('');
    for (const [k, v] of Object.entries(tokens[group])) {
      lines.push(`    <x:Double x:Key="${cap(group)}${cap(k)}">${v}</x:Double>`);
    }
  }
  emit('windows/Keystone/Theme/Tokens.xaml', `<!-- ${HEADER} -->
<ResourceDictionary
    xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
    xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">
${lines.join('\n')}
</ResourceDictionary>
`);
  emit('windows/Keystone/Assets/seed.json', seedText);
}

/* ---------- binary assets ---------- */
for (const f of readdirSync(join(root, 'shared/fonts'))) {
  const data = readFileSync(join(root, 'shared/fonts', f));
  emit(`apple/Sources/KeystoneApp/Resources/Fonts/${f}`, data);
  emit(`windows/Keystone/Assets/Fonts/${f}`, data);
}
const logo = readFileSync(join(root, 'shared/logo.png'));
emit('apple/Sources/KeystoneApp/Resources/logo.png', logo);
emit('windows/Keystone/Assets/logo.png', logo);

if (check && stale.length) {
  console.error('Generated files are out of date. Run `node scripts/sync-shared.mjs` and commit:\n  ' + stale.join('\n  '));
  process.exit(1);
}
if (check) console.log('Generated files are up to date.');
